670: /// instant, evaluated at `now`: (1) a known future reset beats a known past reset beats a missing
671: /// one (a past reset means the window is reset, whatever its share); (2) the higher
672: /// `used_percent`; (3) the later `resets_at`; (4) identical - either. `Greater` when `a` ranks
673: /// above `b`.
674: fn cmp_window_rank(
675:     a: (f64, Option<DateTime<FixedOffset>>),
676:     b: (f64, Option<DateTime<FixedOffset>>),
677:     now: DateTime<Utc>,
678: ) -> std::cmp::Ordering {
679:     let rank = |r: Option<DateTime<FixedOffset>>| match r {
680:         Some(t) if t.with_timezone(&Utc) > now => 2u8,
681:         Some(_) => 1,
682:         None => 0,
683:     };
684:     rank(a.1)
685:         .cmp(&rank(b.1))
686:         .then(a.0.clamp(0.0, 100.0).total_cmp(&b.0.clamp(0.0, 100.0)))
687:         .then(a.1.cmp(&b.1))
