1153: /// The ONE selection of the endpoint window (recorded and live): a candidate strictly newer than
1154: /// `best` replaces it; at an EQUAL `observed_at` (the ledger serialises without fractions, so ties
1155: /// happen) the windows merge PER WINDOW - the higher primary `used_percent` keeps its own reset,
1156: /// and independently the higher secondary - so a blocking weekly window is never hidden behind a
1157: /// fuller 5-hour one. `source` of the result is the candidate's when it contributed a window.
1158: fn select_window(
1159:     best: Option<EndpointWindow>,
1160:     cand_at: [Option<DateTime<FixedOffset>>; 2],
1161:     quota: &Value,
1162:     source: &'static str,
1163:     fingerprint: String,
1164:     now: DateTime<Utc>,
1165: ) -> Option<EndpointWindow> {
1166:     const KEYS: [&str; 2] = ["primary", "secondary"];
1167:     // a window is VALID with a finite share AND an instant; an invalid one never replaces
1168:     let cand_valid = |k: usize| quota_used(quota, KEYS[k]).is_some() && cand_at[k].is_some();
1169:     if !cand_valid(0) && !cand_valid(1) {
1170:         return best;
1171:     }
1172:     let Some(mut out) = best else {
1173:         let mut w = EndpointWindow {
1174:             quota: json!({"primary": null, "secondary": null, "observed_at": quota["observed_at"].clone()}),
1175:             observed_at: cand_at[0].or(cand_at[1])?,
1176:             window_at: [None, None],
1177:             source,
1178:             fingerprint,
1179:         };
1180:         for k in 0..2 {
1181:             if cand_valid(k) {
1182:                 w.quota[KEYS[k]] = quota[KEYS[k]].clone();
1183:                 w.window_at[k] = cand_at[k];
1184:             }
1185:         }
1186:         w.observed_at = w.window_at.iter().flatten().max().copied()?;
1187:         stamp_window_instants(&mut w);
1188:         return Some(w);
1189:     };
1190:     let mut took = false;
1191:     for k in 0..2 {
1192:         if !cand_valid(k) {
1193:             continue;
1194:         }
1195:         let take = match (quota_used(&out.quota, KEYS[k]), out.window_at[k]) {
1196:             (Some(cu), Some(cur_at)) => match cand_at[k].cmp(&Some(cur_at)) {
1197:                 std::cmp::Ordering::Greater => true,
1198:                 std::cmp::Ordering::Less => false,
1199:                 std::cmp::Ordering::Equal => {
1200:                     let reset = |q: &Value| when_offset(&q[KEYS[k]]["resets_at"]);
1201:                     cmp_window_rank(
1202:                         (quota_used(quota, KEYS[k]).unwrap_or(0.0), reset(quota)),
1203:                         (cu, reset(&out.quota)),
1204:                         now,
1205:                     ) == std::cmp::Ordering::Greater
1206:                 }
1207:             },
1208:             _ => true,
1209:         };
1210:         if take {
1211:             out.quota[KEYS[k]] = quota[KEYS[k]].clone();
1212:             out.window_at[k] = cand_at[k];
1213:             took = true;
1214:         }
1215:     }
1216:     if took {
1217:         out.source = source;
1218:         if let Some(l) = out.window_at.iter().flatten().max().copied() {
1219:             if l > out.observed_at {
1220:                 out.quota["observed_at"] = quota["observed_at"].clone();
1221:                 out.fingerprint = fingerprint;
1222:             }
1223:             out.observed_at = l;
1224:         }
1225:         stamp_window_instants(&mut out);
1226:     }
