386: pub fn rollout_usage(
387:     path: &Path,
388:     before: Option<DateTime<FixedOffset>>,
389:     tail_bytes: u64,
390: ) -> RolloutUsage {
391:     let mut r = RolloutUsage {
392:         path: path.to_path_buf(),
393:         ..Default::default()
394:     };
395:     if path.as_os_str().is_empty() || !path.is_file() {
396:         return r;
397:     }
398:     r.found = true;
399:     r.bytes = std::fs::metadata(path).map(|m| m.len()).unwrap_or(0);
400:     let mut prev_total: Option<Value> = None;
401:     let mut last_limits: Option<Observation> = None;
402:     for ev in token_events(&read_rollout_text(path, tail_bytes)) {
403:         let in_run = match before {
404:             None => true,
405:             Some(b) => ev.at.map(|a| a >= b).unwrap_or(false),
406:         };
407:         if let Some(t) = ev.total {
408:             r.total = Some(t);
409:             if let (Some(b), Some(a)) = (before, ev.at) {
410:                 if a < b {
411:                     r.baseline = Some(t);
412:                 }
413:             }
414:             if in_run && ev.total_key != prev_total {
415:                 r.calls += 1;
416:                 if let Some(li) = ev.last_input {
417:                     if r.max_input.map(|m| li > m).unwrap_or(true) {
418:                         r.max_input = Some(li);
419:                     }
420:                 }
421:             }
422:             prev_total = ev.total_key.clone();
423:         }
424:         if ev.context_window.is_some() {
425:             r.context_window = ev.context_window;
426:         }
427:         if ev.has_limits {
428:             let w = Observation {
429:                 primary: ev.primary,
430:                 secondary: ev.secondary,
431:                 at: ev.at,
432:                 primary_at: None,
433:                 secondary_at: None,
434:                 limit_id: ev.limit_id,
435:             };
436:             if w.named() {
437:                 r.window = Some(w.clone());
438:             }
439:             last_limits = Some(w);
440:         }
441:     }
442:     if r.window.is_none() {
443:         r.window = last_limits;
444:     }
445:     r
446: }
