1094: /// The observations of the account's last 16 rollouts (today and yesterday, local) on the built-in
1095: /// `openai` provider that name a window - read from disk, no selection.
1096: fn read_account_observations(codex_home: &str) -> Vec<(Observation, PathBuf)> {
1097:     let mut out = Vec::new();
1098:     let root = Path::new(codex_home).join("sessions");
1099:     if !root.is_dir() {
1100:         return out;
1101:     }
1102:     let today = Local::now().date_naive();
1103:     let mut files: Vec<(SystemTime, PathBuf)> = Vec::new();
1104:     for d in local_day_dirs(&root, today.pred_opt().unwrap_or(today), today) {
1105:         rollouts_in(&d, None, &mut files);
1106:     }
1107:     files.sort_by_key(|(t, _)| std::cmp::Reverse(*t));
1108:     let provider_re = regex::Regex::new(r#""model_provider"\s*:\s*"([^"]*)""#).unwrap();
1109:     for (_, p) in files.into_iter().take(16) {
1110:         let head = read_rollout_head(&p);
1111:         if let Some(c) = provider_re.captures(&head) {
1112:             if &c[1] != "openai" {
1113:                 continue;
1114:             }
1115:         }
1116:         let u = rollout_usage(&p, None, ROLLOUT_TAIL_BYTES);
1117:         if let Some(w) = u.window {
1118:             out.push((w, p));
1119:         }
1120:     }
1121:     out
1122: }

